using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using MiniStore.Domain.Entities;
namespace MiniStore.Infrastructure.Persistence.Configurations;
public sealed class CustomerReturnReceiptConfiguration:IEntityTypeConfiguration<CustomerReturnReceipt>,IEntityTypeConfiguration<CustomerReturnReceiptLine>,IEntityTypeConfiguration<CustomerReturnReceiptHistory>
{
 public void Configure(EntityTypeBuilder<CustomerReturnReceipt>b){b.ToTable("CustomerReturnReceipts");b.HasKey(x=>x.Id);b.Property(x=>x.ReceiptNumber).HasMaxLength(50).IsRequired();b.HasIndex(x=>x.ReceiptNumber).IsUnique();b.Property(x=>x.Notes).HasMaxLength(1000);b.Property(x=>x.CreatedByUserId).HasMaxLength(450).IsRequired();b.Property(x=>x.InspectedByUserId).HasMaxLength(450);b.Property(x=>x.PostedByUserId).HasMaxLength(450);b.Property(x=>x.CancelledByUserId).HasMaxLength(450);b.Property(x=>x.CancellationReason).HasMaxLength(500);b.Property(x=>x.RowVersion).IsRowVersion();b.Ignore(x=>x.TotalReceivedQuantity);b.HasIndex(x=>new{x.CustomerReturnRequestId,x.Status});b.HasOne<CustomerReturnRequest>().WithMany().HasForeignKey(x=>x.CustomerReturnRequestId).OnDelete(DeleteBehavior.Restrict);b.HasMany(x=>x.Lines).WithOne().HasForeignKey(x=>x.CustomerReturnReceiptId).OnDelete(DeleteBehavior.Restrict);b.HasMany(x=>x.History).WithOne().HasForeignKey(x=>x.CustomerReturnReceiptId).OnDelete(DeleteBehavior.Restrict);}
 public void Configure(EntityTypeBuilder<CustomerReturnReceiptLine>b){b.ToTable("CustomerReturnReceiptLines",t=>t.HasCheckConstraint("CK_CustomerReturnReceiptLines_Quantity","[ReceivedQuantity] > 0"));b.HasKey(x=>x.Id);b.Property(x=>x.ReceivedQuantity).HasPrecision(18,6);b.Property(x=>x.UnitCostSnapshot).HasPrecision(18,8);b.Property(x=>x.InspectionNotes).HasMaxLength(500).IsRequired();b.Property(x=>x.TrackingAllocations).HasMaxLength(4000);b.Property(x=>x.ProductCodeSnapshot).HasMaxLength(100).IsRequired();b.Property(x=>x.ProductNameSnapshot).HasMaxLength(200).IsRequired();b.HasIndex(x=>new{x.CustomerReturnReceiptId,x.CustomerReturnRequestLineId}).IsUnique();b.HasOne<CustomerReturnRequestLine>().WithMany().HasForeignKey(x=>x.CustomerReturnRequestLineId).OnDelete(DeleteBehavior.Restrict);b.HasOne<SalesDeliveryLine>().WithMany().HasForeignKey(x=>x.SalesDeliveryLineId).OnDelete(DeleteBehavior.Restrict);b.HasOne<Product>().WithMany().HasForeignKey(x=>x.ProductId).OnDelete(DeleteBehavior.Restrict);b.HasOne<Warehouse>().WithMany().HasForeignKey(x=>x.WarehouseId).OnDelete(DeleteBehavior.Restrict);b.HasOne<StorageLocation>().WithMany().HasForeignKey(x=>x.StorageLocationId).OnDelete(DeleteBehavior.Restrict);}
 public void Configure(EntityTypeBuilder<CustomerReturnReceiptHistory>b){b.ToTable("CustomerReturnReceiptHistories");b.HasKey(x=>x.Id);b.Property(x=>x.UserId).HasMaxLength(450).IsRequired();b.Property(x=>x.Reason).HasMaxLength(500);b.HasIndex(x=>new{x.CustomerReturnReceiptId,x.CreatedAtUtc});}
}
